import { type RegistryWriteOptions } from "./registry";
export type RegistryDatabaseStatus = "present" | "missing";
export type RegistryCheckoutStatus = "active" | "stale" | "inconclusive";
export type RegistryMemoryCheckoutClassification = "single_active" | "multiple_active" | "mixed" | "stale_only" | "inconclusive";
export interface RegistryCheckoutSummary {
    memory_key: string;
    checkout_fingerprint: string;
    scope: "global";
    repo_root: string;
    config_path: string;
    database_path: string;
    database_status: RegistryDatabaseStatus;
    checkout_status: RegistryCheckoutStatus;
    stale: boolean;
    package_version: string;
    config_hash: string;
    git_head: string | null;
    last_seen_at: string;
}
export interface RegistryMemorySummary {
    memory_key: string;
    repository_identity: string | null;
    checkout_count: number;
    active_checkout_count: number;
    stale_checkout_count: number;
    inconclusive_checkout_count: number;
    checkout_classification: RegistryMemoryCheckoutClassification;
    effective_database_paths: string[];
    checkouts: RegistryCheckoutSummary[];
}
export interface RegistryListResult {
    global_home: string;
    registry_path: string;
    memory_count: number;
    checkout_count: number;
    memories: RegistryMemorySummary[];
}
export interface RegistryDoctorFinding {
    code: "stale_path" | "missing_database" | "duplicate_key" | "corrupt_metadata";
    severity: "warning" | "error";
    message: string;
    guidance: string;
    memory_key?: string;
    checkout_fingerprint?: string;
}
export interface RegistryDoctorResult {
    healthy: boolean;
    global_home: string;
    registry_path: string;
    memory_count: number;
    checkout_count: number;
    findings: RegistryDoctorFinding[];
}
export interface RegistryPruneResult {
    dry_run: boolean;
    stale_count: number;
    pruned_count: number;
    entries: RegistryCheckoutSummary[];
    empty_memory_keys: string[];
}
export interface RegistryMaintenanceOptions {
    globalHome?: string;
}
export interface PruneRegistryOptions extends RegistryMaintenanceOptions, Pick<RegistryWriteOptions, "lockTimeoutMs" | "lockRetryMs"> {
    force?: boolean;
}
export declare function listRegistry(options?: RegistryMaintenanceOptions): RegistryListResult;
export declare function showRegistryMemory(memoryKey: string, options?: RegistryMaintenanceOptions): RegistryMemorySummary;
export declare function doctorRegistry(options?: RegistryMaintenanceOptions): RegistryDoctorResult;
export declare function pruneRegistry(options?: PruneRegistryOptions): RegistryPruneResult;
